@Configuration
@Profile("onprem", "onprem_local")
class VllmAuthInterceptorConfig {
    @Bean
    fun vllmAuthInterceptor(...): VllmAuthInterceptor? = when (appProperties.onprem?.site) {
        OnpremSite.SIONIC      -> sionicFactory.create()        // 정적 API key
        OnpremSite.CUSTOMER_A  -> customerAFactory.create()     // requireComplete() 로 env 검증
        OnpremSite.DEFAULT     -> null                           // 인증 없음 (명시적 선택)
        null -> throw IllegalStateException("onprem 프로파일에는 app.onprem 설정이 필수입니다.")
    }   // else 없음 — 고객사를 추가하고 분기를 빠뜨리면 컴파일 에러
}

